    const M = 357.52911 + JC * (35999.05029 - 0.0001537 * JC);
    const e = 0.016708634 - JC * (0.000042037 + 0.0000001267 * JC);
    const C = sin(M) * (1.914602 - JC * (0.004817 + 0.000014 * JC)) + sin(2 * M) * (0.019993 - 0.000101 * JC) + 0.000289 * sin(3 * M);
    const trueLon = L0 + C;
