    const ye = r * (sin(N) * cos(vw) + cos(N) * sin(vw) * cos(i));
    const ze = r * sin(vw) * sin(i);
    let lon = Math.atan2(ye, xe) * R2D, lat = Math.atan2(ze, Math.hypot(xe, ye)) * R2D;
    const Lm = N + w + M, D = Lm - Ls, F = Lm - N;
