      mode = isRich ? 'rich' : 'legacy'; stats.mode = mode;
      if (isRich && (rich.terrain > 0 || rich.breeze > 0 || rich.thermals > 0)) ensureRelief();
      C.t = NaN;                                            // the cache is the old field's
      version++;
