  const H = Math.max(...sta.map(s => s.yd)) - Math.min(...sta.map(s => s.yk));
  const If = [P.mFloat / 12 * (H * H + P.B * P.B), P.mFloat / 12 * (P.L * P.L + P.B * P.B), P.mFloat / 12 * (P.L * P.L + H * H)];
  const I = [0, 0, 0];
