      const g9 = 9.81;
      if (!tOn) { tOn = true; tIthr = clamp(c.thr - tThrCruise, -0.3, 0.3); tIpit = 0; tHdot = vcg[1]; tWk = 1; }
      tHdot += 0.5 * (vcg[1] - tHdot);
