          const d = ap.xAim - sAl;
          const hGS = aimAlt() + Math.max(0, d) * SEL.gs;
          holdVS(clamp(-(o_.Vg ?? V) * SEL.gs + 0.12 * (hGS - cg[1]), Math.min(-3.0, -1.6 * V * SEL.gs), 0.5));
