        const fast = V > 1.35 * (A.VRot || 18);
        const cap = ap.phase === 'FLARE' ? (fast ? (A.apAssistFlareFast ?? 0.12) : (A.apAssistFlare ?? 0.30))
                  : (A.apAssistMax ?? 0.40);
